/**
 * Complementary and alternative products, gap round November 2026, botanicals part: mushrooms, herbs, Chinese
 * formulas, teas, juices and named alternative regimens from Memorial Sloan Kettering's About Herbs database
 * that had no graded record (gap census type `complementary-alternative`). Drug interactions with medicines
 * that have no OnCo record (warfarin, cyclosporine, digoxin, phenytoin, paracetamol) are named in prose only. Same rules as src/data/complementary.ts: a grade tag
 * `evidence:<grade>`, a number only where the linked source states it, interactions and harms taken from MSK's
 * page or the NCI PDQ summary, and no claim of benefit the evidence does not carry. MSK is summarised in our own
 * words and quoted only briefly with attribution. Each MSK page was read as raw text on the asOf date; its own
 * "last updated" date is given in the link label so a reader can see how current it is.
 *
 * Records are spread into `complementary` and their index rows into COMPLEMENTARY_INDEX in complementary.ts,
 * so the hub at /live/complementary/ and the complementary tests cover them.
 */

const asOf = "2026-11-04";
const pdq = (label: string, slug: string) => ({ label: `NCI PDQ: ${label}`, url: `https://www.cancer.gov/about-cancer/treatment/cam/hp/${slug}-pdq` });
